#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.17337597500000002, 0.053909900000000004, -0.054843615000000005], 'basis': [[0.0, 0.6155216007448115, 0.7881200156172568], [0.06552946728539033, 0.7864260577031862, -0.6141986198964614], [-0.9978506345727766, 0.051645084780352346, -0.040334802599458215]], 'axis': [0.7881200156172568, -0.6141986198964614, -0.040334802599458215], 'zmin': -0.041071160640529326, 'zmax': 0.036304349905449194, 'profiles': [{'outer': [[-0.020151152830532704, -0.03074686376083035], [-0.008297604325848026, -0.020299977424610007], [-0.002198240149341086, -0.0217993076244568], [0.005041423299301118, -0.023835731172898743], [0.004756081871601131, -0.018087535544598344], [0.006290849375091781, -0.013883237364500577], [0.004346289050735365, -0.014185018569443125], [0.004349145150381478, -0.012889237390377924], [-0.007701534470295499, -0.015677500689284304], [-0.016606168470954533, -0.006234703343430888], [-0.024491928355099734, 0.0036529758995469427], [-0.035064131176683194, 0.02767176854856075], [-0.03928131702774821, 0.05272783385673081], [-0.03826051035690536, 0.07811074473660598], [-0.03424720860633664, 0.09274168232255524], [-0.021452909464208525, 0.09572076904181838], [-0.02151896696924439, 0.09598787929619805], [-0.020181428431864313, 0.09645368757594565], [-0.017519555558355594, 0.0971532026841004], [-0.020233767539056625, 0.09821189536017616], [-0.022653308841512242, 0.09952259592858012], [-0.02365813666246439, 0.10185925022748567], [-0.031181685767670535, 0.10114987146821838], [-0.03856742773127189, 0.10251480660469488], [-0.04245162657819568, 0.106043329467872], [-0.04392718307241557, 0.11222088365717425], [-0.04360535701456426, 0.11967599294480902], [-0.04202076223119797, 0.12691788589694644], [-0.039312565302557105, 0.13365776848298164], [-0.03516599665734071, 0.1404322689093948], [-0.03080271735351101, 0.14556105379795686], [-0.025891815290795962, 0.14936985411552098], [-0.01981423332160227, 0.15223272790265704], [-0.0133457874247628, 0.1532988572752943], [-0.007590388688645844, 0.1528669136983531], [-0.001833778314854612, 0.15090516979447968], [0.004431899793168226, 0.14737278417403588], [0.009376448739393434, 0.14304004915335883], [0.01356486999342711, 0.13762797105381983], [0.016715592123757724, 0.13129195641369837], [0.01768843914247956, 0.12493476511079409], [0.015214929723663489, 0.11940105977149071], [0.014437269703816666, 0.11861962568751318], [0.008756878428418284, 0.1136980664019245], [0.0024158629624071253, 0.11025595245686047], [0.0026678001065837407, 0.10946012694905448], [0.0015325753751493296, 0.10599165394523644], [-0.0015468909553258512, 0.10106733630717106], [0.002141299042772537, 0.10180895388835856], [0.0023706651265567613, 0.10088149486236435], [0.016347004400918082, 0.10368755882506624], [0.02757082003064886, 0.09242011385511989], [0.03900268019049003, 0.06973486722178382], [0.045525710434477604, 0.04517597571442028], [0.04582542441087341, 0.018930758841732318], [0.04268463058128921, 0.0066609771635304125], [0.03820387194891712, -0.0042836177869727135], [0.03689939348359064, -0.004721090164141563], [0.02955114390028505, -0.006632447903864163], [0.03018400316792165, -0.007843827619025868], [0.028328406187248578, -0.008468432464639528], [0.0316194376370342, -0.01147008579697749], [0.0340845382180313, -0.016745060273015033], [0.034327397698409146, -0.022596928227007568], [0.0323556795703661, -0.028064096945094784], [0.029574448422789362, -0.03113251303647136], [0.03424332664037375, -0.032588530916271646], [0.04149118506801838, -0.03506034136476517], [0.044182296253640056, -0.045209091220393655], [0.04638764186718501, -0.05093376637861121], [0.04497034600683701, -0.07620980847091136], [0.03877221929838197, -0.10083511013740987], [0.025890173020604756, -0.12380608444560356], [0.01704477623713582, -0.13291799134355353], [0.007921987642840897, -0.1403307187708973], [-0.0006779114095928903, -0.1382910573148135], [-0.0031056757503955686, -0.14290427256966332], [-0.007640653013487285, -0.14658465020147834], [-0.013211450737909513, -0.14831304501098364], [-0.019041929057030775, -0.147741179823118], [-0.02416780385679456, -0.14500397575512664], [-0.027896399319634668, -0.14050736291344987], [-0.02958536411485458, -0.1349099718925944], [-0.029152936962812123, -0.1307101553858047], [-0.036579367162441714, -0.12849985294328284], [-0.03716871003520678, -0.1281122216478234], [-0.040338398990875865, -0.11550870580758074], [-0.042775549358920174, -0.102957412251818], [-0.040976459588102476, -0.07662232016959146], [-0.03273070008102024, -0.05262215937742506]], 'holes': []}], 'simplify_tolerance': 6.032238045725559e-05, 'sketch_entity_count': 90}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
